python -c "import re, pathlib, subprocess, sys; txt = pathlib.Path('templates/converter/base.html').read_text(encoding='utf-8'); scripts = re.findall(r'<script[^>]*>(.*?)</script>', txt, re.S); print(f'Found {len(scripts)} script blocks'); i=0; 
for s in scripts:
    p = pathlib.Path(f'tmp_script_{i}.js');
    p.write_text(s, encoding='utf-8');
    r = subprocess.run(['node','--check', str(p)], capture_output=True, text=True);
    print('BLOCK', i, 'RC', r.returncode)
    if r.stdout: print(r.stdout)
    if r.stderr: print(r.stderr)
    p.unlink(missing_ok=True)
    i += 1"
